var e=[{question:`¿Qué es EducaLabCR?`,answer:`EducaLabCR integra tecnología, formación e innovación aplicada en Costa Rica. El ecosistema reúne Sigma Docente, TEKU, LUMA, Relay, la práctica de idoneidad docente y taskOs.`},{question:`¿Qué es Sigma Docente?`,answer:`Sigma Docente es la plataforma de registro y gestión educativa. Incluye asistencia, reportes de notas, Lápiz para generar materiales con inteligencia artificial y Ágora. Hay una demostración pública.`},{question:`¿Qué es TEKU?`,answer:`TEKU es un piloto para investigar y escribir una tesis o un proyecto, con tutor socrático y editor con fuentes. El piloto está en línea.`},{question:`¿Qué es LUMA?`,answer:`LUMA genera presentaciones en español, con modo Docente IA y 18 familias visuales. No hay una dirección pública verificada: el acceso se consulta con el equipo. Este sitio no publica planes ni cupos de uso.`},{question:`¿Qué es Relay?`,answer:`Relay es la plataforma de agentes conversacionales, con base de conocimiento y atención en tiempo real. El panel está en línea. Relay Ventas, el agente de WhatsApp, es un producto distinto y se consulta aparte.`},{question:`¿Qué es la práctica de idoneidad docente?`,answer:`Es un simulador de las pruebas de idoneidad docente del MEP, con tutoría de inteligencia artificial. El acceso se consulta con el equipo porque no hay una dirección pública verificada.`},{question:`¿Qué es taskOs?`,answer:`taskOs es el gestor de tareas para una institución o para varias organizaciones. La aplicación está en línea.`},{question:`¿Hay formación para docentes?`,answer:`Sí. Hay una oferta formativa para docentes. El catálogo publicado aquí sale del sitio anterior y falta confirmar vigencia e inscripción.`},{question:`¿Cómo me comunico con EducaLabCR?`,answer:`Por WhatsApp, al +506 7014 7031. Es el canal publicado. No hay un correo público confirmado en este sitio.`}];
